package bookstore

import "github.com/google/uuid"

// Book represents a book in the bookstore.
type Book struct {
	ID     string `json:"id"`
	Title  string `json:"title"`
	Author string `json:"author"`
	Pages  int    `json:"pages"`
}

// CreateBookRequest represents the request body for creating a new book.
type CreateBookRequest struct {
	Title  string `json:"title" validate:"required,min=3"`
	Author string `json:"author" validate:"required,min=3"`
	Pages  int    `json:"pages" validate:"required,min=1"`
}

// NewBook creates a new Book with a generated ID.
func NewBook(req CreateBookRequest) Book {
	return Book{
		ID:     uuid.New().String(),
		Title:  req.Title,
		Author: req.Author,
		Pages:  req.Pages,
	}
}

package bookstore

import (
	"fmt"
	"sync"
)

// Store provides an in-memory storage for books.
type Store struct {
	mu    sync.RWMutex
	books map[string]Book
}

// NewStore creates and returns a new in-memory Store.
func NewStore() *Store {
	return &Store{
		books: make(map[string]Book),
	}
}

// AddBook adds a new book to the store.
func (s *Store) AddBook(book Book) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.books[book.ID] = book
}

// GetBook returns a book by its ID. Returns an error if the book is not found.
func (s *Store) GetBook(id string) (Book, error) {
	s.mu.RLock()
	defer s.mu.Rnlock()

	book, ok := s.books[id]
	if !ok {
		return Book{}, fmt.Errorf("book with ID %s not found", id)
	}
	return book, nil
}

// ListBooks returns all books in the store.
func (s *Store) ListBooks() []Book {
	s.mu.RLock()
	defer s.mu.RUnlock()

	books := make([]Book, 0, len(s.books))
	for _, book := range s.books {
		books = append(books, book)
	}
	return books
}

package bookstore

import (
	"encoding/json"
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/go-playground/validator/v10"
)

// API represents the API service with its dependencies.
type API struct {
	store    *Store
	validator *validator.Validate
}

// NewAPI creates and returns a new API instance.
func NewAPI(store *Store) *API {
	return &API{
		store:    store,
		validator: validator.New(),
	}
}

// handleListBooks godoc
// @Summary List all books
// @Produce json
// @Success 200 {array} Book
// @Router /books [get]
func (api *API) handleListBooks(w http.ResponseWriter, r *http.Request) {
	books := api.store.ListBooks()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(books)
}

// handleCreateBook godoc
// @Summary Create a book
// @Accept json
// @Produce json
// @Param book body CreateBookRequest true "Book to create"
// @Success 201 {object} Book
// @Failure 400 {string} string "Invalid input"
// @Router /books [post]
func (api *API) handleCreateBook(w http.ResponseWriter, r *http.Request) {
	var req CreateBookRequest
	err := json.NewDecoder(r.Body).Decode(&req)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if err := api.validator.Struct(req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	book := NewBook(req)
	api.store.AddBook(book)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(book)
}

// handleGetBook godoc
// @Summary Get a book by ID
// @Produce json
// @Param id path string true "Book ID"
// @Success 200 {object} Book
// @Failure 404 {string} string "Book not found"
// @Router /books/{id} [get]
func (api *API) handleGetBook(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	book, err := api.store.GetBook(id)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(book)
}

package bookstore

import (
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

// NewRouter creates and configures a new Chi router for the bookstore API.
func NewRouter(api *API) http.Handler {
	r := chi.NewRouter()

	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)

	r.Get("/books", api.handleListBooks)
	r.Post("/books", api.handleCreateBook)
	r.Get("/books/{id}", api.handleGetBook)

	return r
}

package main

import (
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"bookstore"
)

func main() {
	ctx := context.Background()

	if err := run(ctx, os.Stdout, os.Args); err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, stdout io.Writer, args []string) error {
	ctx, cancel := signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
	defer cancel()

	store := bookstore.NewStore()
	api := bookstore.NewAPI(store)
	r := bookstore.NewRouter(api)

	httpServer := &http.Server{
		Addr:    ":8080",
		Handler: r,
	}

	go func() {
		log.Printf("Server listening on %s", httpServer.Addr)
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			fmt.Fprintf(os.Stderr, "Server error: %s\n", err)
		}
	}()

	<-ctx.Done()

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	if err := httpServer.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("server shutdown error: %w", err)
	}

	log.Println("Server gracefully stopped")

	return nil
}

package bookstore

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
)

func TestListBooks(t *testing.T) {
	store := NewStore()
	api := NewAPI(store)

	// Add some dummy books
	store.AddBook(NewBook(CreateBookRequest{Title: "Book 1", Author: "Author 1", Pages: 100}))
	store.AddBook(NewBook(CreateBookRequest{Title: "Book 2", Author: "Author 2", Pages: 200}))

	req, _ := http.NewRequest("GET", "/books", nil)
	rr := httptest.NewRecorder()

	api.handleListBooks(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var books []Book
	if err := json.NewDecoder(rr.Body).Decode(&books); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if len(books) != 2 {
		t.Errorf("handler returned wrong number of books: got %v want %v", len(books), 2)
	}
}

func TestCreateBook(t *testing.T) {
	store := NewStore()
	api := NewAPI(store)

	tests := []struct {
		name       string
		reqBody    CreateBookRequest
		expectStatus int
		expectError  bool
	}{
		{
			name:       "Valid book",
			reqBody:    CreateBookRequest{Title: "New Book", Author: "New Author", Pages: 150},
			expectStatus: http.StatusCreated,
			expectError:  false,
		},
		{
			name:       "Invalid title (too short)",
			reqBody:    CreateBookRequest{Title: "Nu", Author: "New Author", Pages: 150},
			expectStatus: http.StatusBadRequest,
			expectError:  true,
		},
		{
			name:       "Invalid pages (zero)",
			reqBody:    CreateBookRequest{Title: "New Book", Author: "New Author", Pages: 0},
			expectStatus: http.StatusBadRequest,
			expectError:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			body, _ := json.Marshal(tt.reqBody)
			req, _ := http.NewRequest("POST", "/books", bytes.NewBuffer(body))
			req.Header.Set("Content-Type", "application/json")
			rr := httptest.NewRecorder()

			api.handleCreateBook(rr, req)

			if status := rr.Code; status != tt.expectStatus {
				t.Errorf("handler returned wrong status code: got %v want %v", status, tt.expectStatus)
			}

			if !tt.expectError {
				var book Book
				if err := json.NewDecoder(rr.Body).Decode(&book); err != nil {
					t.Fatalf("could not decode response: %v", err)
				}
				if book.Title != tt.reqBody.Title {
					t.Errorf("handler returned unexpected book title: got %v want %v", book.Title, tt.reqBody.Title)
				}
				if book.ID == "" {
					t.Error("handler returned book with empty ID")
				}
			}
		})
	}
}

func TestGetBook(t *testing.T) {
	store := NewStore()
	api := NewAPI(store)

	existingBook := NewBook(CreateBookRequest{Title: "Existing Book", Author: "Existing Author", Pages: 300})
	store.AddBook(existingBook)

	// Create a new router for testing with URL parameters
	r := chi.NewRouter()
	r.Get("/books/{id}", api.handleGetBook)

	tests := []struct {
		name       string
		bookID     string
		expectStatus int
		expectError  bool
	}{
		{
			name:       "Book found",
			bookID:     existingBook.ID,
			expectStatus: http.StatusOK,
			expectError:  false,
		},
		{
			name:       "Book not found",
			bookID:     "non-existent-id",
			expectStatus: http.StatusNotFound,
			expectError:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req, _ := http.NewRequest("GET", "/books/"+tt.bookID, nil)
			rr := httptest.NewRecorder()

			r.ServeHTTP(rr, req) // Use the router to handle the request for URL params

			if status := rr.Code; status != tt.expectStatus {
				t.Errorf("handler returned wrong status code: got %v want %v", status, tt.expectStatus)
			}

			if !tt.expectError {
				var book Book
				if err := json.NewDecoder(rr.Body).Decode(&book); err != nil {
					t.Fatalf("could not decode response: %v", err)
				}
				if book.ID != existingBook.ID {
					t.Errorf("handler returned unexpected book ID: got %v want %v", book.ID, existingBook.ID)
				}
			}
		})
	}
}
